<?php declare(strict_types=1); require __DIR__.'/admin-empresa-action-common.php'; admin_empresa_post(); [$app,$session,$user]=admin_empresa_context(); try{$app->companyAdmin()->leave($user->id());$session->regenerate();$session->flash('success','Acesso administrativo encerrado.');}catch(Throwable $e){error_log('Company support leave failed: '.get_class($e));$session->flash('danger','Não foi possível encerrar o acesso.');}admin_empresa_redirect($app);
